components.css:
.ds-sheet-header{display:flex;height:56px;align-items:center;justify-content:space-between;gap:16px;border-bottom:1px solid var(--color-rule);background:var(--color-sheet);padding:0 28px;font-family:Archivo,'Helvetica Neue',Helvetica,sans-serif;}
.ds-sheet-header__identity{display:flex;min-width:0;align-items:center;gap:14px;}
.ds-seal{display:block;width:11px;height:11px;flex-shrink:0;background:var(--color-navy);}
.ds-sheet-header__title{font-size:11.5px;font-weight:700;letter-spacing:.19em;text-transform:uppercase;color:var(--color-ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.ds-sheet-header__meta{display:flex;flex-shrink:0;align-items:center;gap:16px;}
.ds-move-counter{font-family:'Chivo Mono',ui-monospace,SFMono-Regular,monospace;font-variant-numeric:tabular-nums;font-size:11px;letter-spacing:.14em;color:var(--color-soft);}
.ds-move-counter b{font-size:13px;font-weight:700;letter-spacing:normal;color:var(--color-ink);}
.ds-move-counter__total{color:var(--color-soft);}
.ds-save-status{display:flex;align-items:center;gap:8px;font-family:'Chivo Mono',ui-monospace,SFMono-Regular,monospace;font-size:11px;letter-spacing:.14em;color:var(--color-soft);}
.ds-save-mark{display:block;box-sizing:border-box;width:10px;height:10px;flex-shrink:0;}
.ds-save-mark--saved{background:var(--color-certified);}
.ds-save-mark--saving{border:1px dashed var(--color-ochre);}
.ds-save-mark--error{border:2px solid var(--color-flag);}

.ds-option-band{box-sizing:border-box;position:relative;isolation:isolate;display:flex;align-items:center;min-height:92px;cursor:pointer;border:1px solid var(--color-rule);border-top:0;background:var(--color-sheet);font-family:Archivo,'Helvetica Neue',Helvetica,sans-serif;}
.ds-option-band:first-of-type{border-top:1px solid var(--color-rule);}
.ds-option-band::before{content:'';position:absolute;inset:0;z-index:0;background:var(--color-navy);clip-path:inset(0 100% 0 0);transition:clip-path 460ms cubic-bezier(.16,1,.3,1);}
.ds-option-band:has(input:checked)::before{clip-path:inset(0 0 0 0);}
.ds-option-band>*{position:relative;z-index:1;}
.ds-option-band__input{position:absolute;width:1px;height:1px;opacity:0;}
.ds-option-band__letter{box-sizing:border-box;display:flex;width:58px;align-self:stretch;align-items:center;justify-content:center;border-right:1px solid var(--color-rule);font-family:'Chivo Mono',ui-monospace,SFMono-Regular,monospace;font-variant-numeric:tabular-nums;font-size:15px;font-weight:700;color:var(--color-soft);transition:color 150ms,border-color 150ms;}
.ds-option-band__label{max-width:68ch;padding:16px 28px;font-size:17px;line-height:1.5;color:var(--color-ink);transition:color 150ms;}
.ds-option-band__key{box-sizing:border-box;margin-left:auto;margin-right:20px;display:flex;height:26px;width:30px;align-items:center;justify-content:center;border:1px solid var(--color-rule);font-family:'Chivo Mono',ui-monospace,SFMono-Regular,monospace;font-variant-numeric:tabular-nums;font-size:11px;color:var(--color-soft);transition:color 150ms,border-color 150ms;}
.ds-option-band:hover:not(:has(input:checked)){background:var(--color-paper);}
.ds-option-band:has(input:focus-visible){outline:2px solid var(--color-ochre);outline-offset:-2px;}
.ds-option-band:has(input:checked) .ds-option-band__letter{color:#fff;border-right-color:rgba(238,241,245,.25);}
.ds-option-band:has(input:checked) .ds-option-band__label{color:var(--color-navy-soft);}
.ds-option-band:has(input:checked) .ds-option-band__key{color:var(--color-navy-soft);border-color:rgba(238,241,245,.4);}
@media (prefers-reduced-motion: reduce){.ds-option-band::before{transition-duration:1ms;}}

.ds-move-rail{box-sizing:border-box;display:flex;flex-direction:column;width:104px;border-right:1px solid var(--color-rule);background:var(--color-sheet);padding:20px 16px 16px;font-family:'Chivo Mono',ui-monospace,SFMono-Regular,monospace;}
.ds-move-rail__head{display:flex;align-items:baseline;justify-content:space-between;border-bottom:1px solid var(--color-rule);padding-bottom:8px;font-size:11px;letter-spacing:.18em;color:var(--color-soft);}
.ds-move-rail__list{list-style:none;margin:12px 0 0;padding:0;}
.ds-move-rail__list li{display:flex;align-items:center;gap:10px;height:22px;}
.ds-mark{box-sizing:border-box;display:block;width:12px;height:12px;flex-shrink:0;}
.ds-mark--answered{background:var(--color-navy);}
.ds-mark--unanswered{border:1px solid rgba(90,100,112,.45);background:var(--color-sheet);}
.ds-mark--pending{border:1px dashed var(--color-ochre);background:var(--color-sheet);}
.ds-mark--current{border:2px solid var(--color-ochre);background:linear-gradient(90deg,var(--color-ochre) 50%,#fff 50%);}
.ds-mark__line{flex:1;height:1px;background:var(--color-rule);}
.ds-mark__line--current{height:2px;background:var(--color-ochre);}
.ds-move-rail__result{margin-top:auto;padding-top:16px;}
.ds-move-rail__result-label{display:block;margin-bottom:6px;font-size:10px;letter-spacing:.2em;color:var(--color-soft);}
.ds-result-cell{box-sizing:border-box;display:flex;height:26px;align-items:center;justify-content:center;border:1px solid var(--color-rule);font-size:12px;color:var(--color-soft);}
.ds-mark--skipped{border:1px solid rgba(90,100,112,.45);background:linear-gradient(to top right,transparent calc(50% - .6px),var(--color-soft) calc(50% - .6px),var(--color-soft) calc(50% + .6px),transparent calc(50% + .6px));}

.ds-browser-demo{box-sizing:border-box;display:grid;gap:14px;border:1px solid var(--color-rule);background:var(--color-sheet);padding:20px;font-family:Archivo,'Helvetica Neue',Helvetica,sans-serif;font-size:15px;line-height:1.6;color:var(--color-ink);}
.ds-browser-demo ::selection{background:var(--color-navy);color:var(--color-navy-soft);}
.ds-browser-demo *:focus-visible{outline:2px solid var(--color-ochre);outline-offset:2px;}
.ds-browser-demo__label{font-size:12.5px;color:var(--color-soft);}
.ds-browser-demo__input{box-sizing:border-box;width:100%;margin-top:6px;border:1px solid var(--color-rule);background:transparent;padding:8px 12px;font:inherit;color:var(--color-ink);caret-color:var(--color-ochre);}
.ds-browser-demo__input:focus{border-color:var(--color-ochre);outline:none;}
.ds-browser-demo__scroll{max-height:64px;overflow-y:auto;border-top:1px solid var(--color-rule);padding-top:8px;scrollbar-width:thin;scrollbar-color:var(--color-rule) transparent;font-family:'Chivo Mono',ui-monospace,SFMono-Regular,monospace;font-size:11px;letter-spacing:.06em;color:var(--color-soft);}
.ds-browser-demo__scroll::-webkit-scrollbar{width:10px;height:10px;}
.ds-browser-demo__scroll::-webkit-scrollbar-track{background:transparent;}
.ds-browser-demo__scroll::-webkit-scrollbar-thumb{background-color:var(--color-rule);border:3px solid var(--color-paper);border-radius:0;}
.ds-browser-demo__scroll::-webkit-scrollbar-thumb:hover{background-color:var(--color-soft);}
